#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> graph(n);
    for (int i = 0; i < n - 1; ++i) {
        int first, second;
        cin >> first >> second;
        --first;
        --second;
        graph[first].push_back(second);
        graph[second].push_back(first);
    }
    vector<int> color(n, -1);
    array<vector<int>, 2> classes;
    queue<int> pending;
    pending.push(0);
    color[0] = 0;
    while (!pending.empty()) {
        int vertex = pending.front();
        pending.pop();
        classes[color[vertex]].push_back(vertex);
        for (int next : graph[vertex]) {
            if (color[next] != -1) continue;
            color[next] = color[vertex] ^ 1;
            pending.push(next);
        }
    }
    const auto& chosen = classes[0].size() >= static_cast<size_t>(n / 2) ? classes[0] : classes[1];
    for (int i = 0; i < n / 2; ++i) cout << chosen[i] + 1 << (i + 1 == n / 2 ? '\n' : ' ');
}

