#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, requiredFactors;
    cin >> n >> requiredFactors;
    vector<int> factorCount(n + 1);
    for (int prime = 2; prime <= n; ++prime) {
        if (factorCount[prime] != 0) continue;
        for (int multiple = prime; multiple <= n; multiple += prime) {
            ++factorCount[multiple];
        }
    }
    int answer = 0;
    for (int value = 2; value <= n; ++value) {
        if (factorCount[value] >= requiredFactors) ++answer;
    }
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> time(n, vector<int>(n));
    for (auto &row : time) for (int &value : row) cin >> value;
    int pairCount;
    cin >> pairCount;
    vector<vector<bool>> forbidden(n, vector<bool>(n));
    for (int i = 0; i < pairCount; ++i) {
        int first, second;
        cin >> first >> second;
        --first;
        --second;
        forbidden[first][second] = forbidden[second][first] = true;
    }
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    const int infinity = 1000000000;
    int bestTime = infinity;
    do {
        bool valid = true;
        for (int leg = 1; leg < n; ++leg) {
            if (forbidden[order[leg - 1]][order[leg]]) valid = false;
        }
        if (!valid) continue;
        int totalTime = 0;
        for (int leg = 0; leg < n; ++leg) totalTime += time[order[leg]][leg];
        bestTime = min(bestTime, totalTime);
    } while (next_permutation(order.begin(), order.end()));
    cout << (bestTime == infinity ? -1 : bestTime) << '\n';
}

