#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, typeLimit;
    cin >> n >> typeLimit;
    vector<long long> values(n);
    for (long long &value : values) cin >> value;
    map<long long, int> frequency;
    int left = 0, bestLength = 0;
    for (int right = 0; right < n; ++right) {
        ++frequency[values[right]];
        while (static_cast<int>(frequency.size()) > typeLimit) {
            auto entry = frequency.find(values[left]);
            if (--entry->second == 0) frequency.erase(entry);
            ++left;
        }
        bestLength = max(bestLength, right - left + 1);
    }
    cout << bestLength << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, queryCount;
    cin >> n >> queryCount;
    vector<long long> sumCoordinate(n), differenceCoordinate(n);
    for (int i = 0; i < n; ++i) {
        long long x, y;
        cin >> x >> y;
        sumCoordinate[i] = x + y;
        differenceCoordinate[i] = x - y;
    }
    auto sumBounds = minmax_element(sumCoordinate.begin(), sumCoordinate.end());
    auto differenceBounds = minmax_element(differenceCoordinate.begin(), differenceCoordinate.end());
    while (queryCount--) {
        int point;
        cin >> point;
        --point;
        long long answer = max({
            sumCoordinate[point] - *sumBounds.first,
            *sumBounds.second - sumCoordinate[point],
            differenceCoordinate[point] - *differenceBounds.first,
            *differenceBounds.second - differenceCoordinate[point]
        });
        cout << answer << '\n';
    }
}

