#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> neighbors(n);
    for (int i = 0; i < n - 1; ++i) {
        int first, second;
        cin >> first >> second;
        --first;
        --second;
        neighbors[first].push_back(second);
        neighbors[second].push_back(first);
    }
    vector<int> parent(n, -1), order{0};
    for (int index = 0; index < n; ++index) {
        int vertex = order[index];
        for (int next : neighbors[vertex]) {
            if (next == parent[vertex]) continue;
            parent[next] = vertex;
            order.push_back(next);
        }
    }
    vector<long long> subtreeSize(n, 1);
    long long answer = 0;
    for (int index = n - 1; index > 0; --index) {
        int vertex = order[index];
        answer += subtreeSize[vertex] * (n - subtreeSize[vertex]);
        subtreeSize[parent[vertex]] += subtreeSize[vertex];
    }
    cout << answer << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int digitSum;
    cin >> digitSum;
    if (digitSum % 9 != 0) {
        cout << 0 << '\n';
        return 0;
    }
    const long long mod = 1000000007;
    vector<long long> ways(digitSum + 1);
    ways[0] = 1;
    for (int sum = 1; sum <= digitSum; ++sum) {
        for (int digit = 1; digit <= 9 && digit <= sum; ++digit) {
            ways[sum] = (ways[sum] + ways[sum - digit]) % mod;
        }
    }
    cout << ways[digitSum] << '\n';
}
